import '../../../core/configs/project_config.dart';

/// Fastlane files for CI deployment.
class FastlaneTemplate {
  static String appfile(ProjectConfig config) {
    return '''
# Generated by XProject Generator
app_identifier("${config.iosBundleId}")
package_name("${config.androidPackage}")
'''.trim();
  }

  static String envExample() {
    return '''
# Copy to GitLab CI/CD variables (masked / file). Do not commit secrets.

# Android Play (internal track)
# PLAY_JSON_KEY_FILE — path to service account JSON on runner
# ANDROID_KEYSTORE_BASE64
# KEYSTORE_PASSWORD
# KEY_ALIAS
# KEY_PASSWORD

# TestFlight
# APP_STORE_CONNECT_API_KEY_ID
# APP_STORE_CONNECT_API_ISSUER_ID
# APP_STORE_CONNECT_API_KEY_FILE — path to AuthKey.p8

# Firebase App Distribution
# FIREBASE_APP_ID
# FIREBASE_TOKEN or GOOGLE_APPLICATION_CREDENTIALS
'''.trim();
  }

  static String fastfile(ProjectConfig config) {
    const flavor = ProjectConfig.defaultCiFlavor;
    final targets = config.resolvedDeployTargets;
    final buffer = StringBuffer();

    buffer.writeln('# Generated by XProject Generator');
    buffer.writeln('default_platform(:android)');
    buffer.writeln();
    buffer.writeln('platform :android do');
    if (targets.contains(DeployTarget.playInternal) && config.targetsAndroid) {
      buffer.writeln('  desc "Upload to Play internal testing"');
      buffer.writeln('  lane :deploy_play_internal do');
      buffer.writeln('    upload_to_play_store(');
      buffer.writeln('      track: "internal",');
      buffer.writeln(
        '      aab: "../build/app/outputs/bundle/${flavor}Release/app-$flavor-release.aab",',
      );
      buffer.writeln('      json_key: ENV["PLAY_JSON_KEY_FILE"]');
      buffer.writeln('    )');
      buffer.writeln('  end');
      buffer.writeln();
    }
    if (targets.contains(DeployTarget.firebaseAppDistribution) &&
        config.targetsAndroid) {
      buffer.writeln('  desc "Firebase App Distribution (Android)"');
      buffer.writeln('  lane :deploy_firebase_android do');
      buffer.writeln('    firebase_app_distribution(');
      buffer.writeln('      app: ENV["FIREBASE_APP_ID_ANDROID"],');
      buffer.writeln(
        '      android_artifact_path: "../build/app/outputs/bundle/${flavor}Release/app-$flavor-release.aab",',
      );
      buffer.writeln('      firebase_cli_token: ENV["FIREBASE_TOKEN"]');
      buffer.writeln('    )');
      buffer.writeln('  end');
      buffer.writeln();
    }
    buffer.writeln('end');
    buffer.writeln();
    buffer.writeln('platform :ios do');
    if (targets.contains(DeployTarget.testFlight) && config.targetsIos) {
      buffer.writeln('  desc "Upload to TestFlight"');
      buffer.writeln('  lane :deploy_testflight do');
      buffer.writeln('    upload_to_testflight(');
      buffer.writeln('      api_key_path: ENV["APP_STORE_CONNECT_API_KEY_FILE"],');
      buffer.writeln('      ipa: "../build/ios/ipa/*.ipa"');
      buffer.writeln('    )');
      buffer.writeln('  end');
      buffer.writeln();
    }
    if (targets.contains(DeployTarget.firebaseAppDistribution) &&
        config.targetsIos) {
      buffer.writeln('  desc "Firebase App Distribution (iOS)"');
      buffer.writeln('  lane :deploy_firebase_ios do');
      buffer.writeln('    firebase_app_distribution(');
      buffer.writeln('      app: ENV["FIREBASE_APP_ID_IOS"],');
      buffer.writeln('      ipa_path: Dir.glob("../build/ios/ipa/*.ipa").first,');
      buffer.writeln('      firebase_cli_token: ENV["FIREBASE_TOKEN"]');
      buffer.writeln('    )');
      buffer.writeln('  end');
      buffer.writeln();
    }
    buffer.writeln('end');
    buffer.writeln();

    if (targets.contains(DeployTarget.firebaseAppDistribution) &&
        (config.targetsAndroid || config.targetsIos)) {
      buffer.writeln('desc "Deploy to Firebase (platform-specific lanes)"');
      buffer.writeln('lane :deploy_firebase do');
      if (config.targetsAndroid) {
        buffer.writeln('  deploy_firebase_android if ENV["FIREBASE_APP_ID_ANDROID"]');
      }
      if (config.targetsIos) {
        buffer.writeln('  deploy_firebase_ios if ENV["FIREBASE_APP_ID_IOS"]');
      }
      buffer.writeln('end');
    }

    if (!targets.any(
      (t) =>
          t == DeployTarget.playInternal ||
          t == DeployTarget.testFlight ||
          t == DeployTarget.firebaseAppDistribution,
    )) {
      buffer.writeln('# Artifacts-only: use CI build jobs; no upload lanes.');
    }

    return buffer.toString().trimRight();
  }

  static String smokeTest() {
    return '''
import 'package:flutter_test/flutter_test.dart';

void main() {
  test('smoke', () {
    expect(2 + 2, 4);
  });
}
''';
  }
}
